window.docContents[207].resolve({"/part-2-analysis/#part-2-analysis":{"contents":"Classical real analysis buries intuitive geometric ideas beneath nested quantifier alternations (\\forall \\varepsilon > 0,\\; \\exists \\delta > 0,\\; \\forall x \\dots). Part II replaces those \\varepsilon–\\delta games with direct algebraic statements about unlimited hypernatural indices N \\in \\mathbb{N}^*_\\infty and infinitesimal increments \\Delta x \\in \\mathbb{I}.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lectures on the Hyperreals — Interactive Lean 4 & Spatial Edition","header":"2. Part II — Elementary Analysis via Infinitesimals","id":"/part-2-analysis/#part-2-analysis"}});